import { mkdir, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { build, transform } from "esbuild";

import { rendererClientScript } from "../com.github.copilot/extensions/foundry-agent-playground/renderer/renderer-client.mjs";

const outputUrl = new URL("../com.github.copilot/extensions/foundry-agent-playground/renderer/dist/playground-client.js", import.meta.url);
const banner = [
    "// Generated by `npm run build` from renderer/renderer-client.mjs via esbuild.",
    "// Do not edit this file directly.",
    "",
].join("\n");

const mermaidRuntime = await build({
    stdin: {
        contents: 'import mermaid from "mermaid";\nglobalThis.__castiaMermaid = mermaid;\n',
        sourcefile: "mermaid-runtime.js",
        resolveDir: fileURLToPath(new URL("..", import.meta.url)),
    },
    bundle: true,
    format: "iife",
    platform: "browser",
    target: "es2022",
    minifyWhitespace: true,
    minifySyntax: true,
    minifyIdentifiers: false,
    legalComments: "none",
    write: false,
});

const { code } = await transform(rendererClientScript, {
    loader: "js",
    target: "es2022",
    minifyWhitespace: true,
    minifySyntax: true,
    minifyIdentifiers: false,
    legalComments: "none",
});

await mkdir(new URL(".", outputUrl), { recursive: true });
const generated = banner + mermaidRuntime.outputFiles[0].text + "\n" + code;
await writeFile(outputUrl, generated.replace(/[ \t]+$/gm, ""), "utf8");
